/usr/bin/bash -lc "node - <<'NODE'
const assert = require('node:assert/strict');
const {runTarget, runAdjacent} = require('./src/temporal-flow.js');
(async () => {
  for (const clickBeforeReady of [true, false]) {
    for (const loadedFlag of [true, false]) {
      const value = loadedFlag ? 'premium-action' : 'none';
      assert.deepEqual(await runTarget({clickBeforeReady, loadedFlag}), {value, events:[value]});
    }
  }
  assert.deepEqual(await runAdjacent({clickBeforeReady:true, loadedFlag:true}), {value:'emergency-action', events:['emergency-action']});
  assert.deepEqual(await runAdjacent({clickBeforeReady:false, loadedFlag:true}), {value:'none', events:['none']});
  console.log('6 temporal-flow cases passed');
})().catch(error => { console.error(error); process.exitCode=1; });
